def firstUniqChar(s):
    # Step 1: Build character count dictionary
    count = {}
    for ch in s:
        if ch in count:
            count[ch] += 1
        else:
            count[ch] = 1

    # Step 2: Find the first unique character using its count
    for idx, ch in enumerate(s):
        if count[ch] == 1:
            return idx

    # No unique character found
    return -1
